  UNIQUE INDEX uq_licence_user_invitation_licence_id_invited_email (licence_id, invited_email) WHERE closed_at IS NULL,
  INDEX idx_licence_user_invitation_invited_app_user_id (invited_app_user_id) WHERE invited_app_user_id IS NOT NULL,
  INDEX idx_licence_user_invitation_invited_by_app_user_id (invited_by_app_user_id),
  INDEX idx_licence_user_invitation_expires_at (expires_at) WHERE closed_at IS NULL,
  INDEX idx_licence_user_invitation_licence_invitation_status_id (licence_invitation_status_id),
  INDEX idx_licence_user_invitation_licence_seat_id (licence_seat_id)
);
-- @@
CREATE TABLE IF NOT EXISTS device_slot (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  licence_seat_id UUID NOT NULL,
  slot_no INT4 NOT NULL,
  is_retired BOOL NOT NULL DEFAULT false,
  CONSTRAINT pk_device_slot PRIMARY KEY (id),
  CONSTRAINT uq_device_slot_licence_seat_id_slot_no UNIQUE (licence_seat_id, slot_no),
  CONSTRAINT uq_device_slot_licence_seat_id_id UNIQUE (licence_seat_id, id),
  CONSTRAINT ck_device_slot_slot_no_positive CHECK (slot_no > 0),
  CONSTRAINT fk_device_slot_licence_seat_id FOREIGN KEY (licence_seat_id) REFERENCES licence_seat (id) ON DELETE CASCADE ON UPDATE RESTRICT
);
-- @@
CREATE TABLE IF NOT EXISTS device_limit_violation (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  licence_seat_id UUID NOT NULL,
  app_user_id UUID NOT NULL,
  device_id UUID,
  attempted_fingerprint_hash BYTES NOT NULL,
  active_session_count INT4 NOT NULL,
  max_devices_allowed INT4 NOT NULL,
  device_limit_policy_id UUID NOT NULL,
  replaced_device_session_id UUID,
  login_attempt_id UUID,
  audit_event_id UUID,
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT pk_device_limit_violation PRIMARY KEY (id),
  CONSTRAINT ck_device_limit_violation_count_at_limit CHECK (active_session_count >= max_devices_allowed),
  CONSTRAINT fk_device_limit_violation_licence_seat_id FOREIGN KEY (licence_seat_id) REFERENCES licence_seat (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_device_limit_violation_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_device_limit_violation_device_id FOREIGN KEY (device_id) REFERENCES device (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_device_limit_violation_device_limit_policy_id FOREIGN KEY (device_limit_policy_id) REFERENCES device_limit_policy (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_device_limit_violation_login_attempt_id FOREIGN KEY (login_attempt_id) REFERENCES login_attempt (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_device_limit_violation_audit_event_id FOREIGN KEY (audit_event_id) REFERENCES audit_event (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  INDEX idx_device_limit_violation_licence_seat_id_occurred_at (licence_seat_id, occurred_at DESC),
  INDEX idx_device_limit_violation_app_user_id_occurred_at (app_user_id, occurred_at DESC),
  INDEX idx_device_limit_violation_device_id (device_id) WHERE device_id IS NOT NULL,
  INDEX idx_device_limit_violation_replaced_device_session_id (replaced_device_session_id) WHERE replaced_device_session_id IS NOT NULL,
  INDEX idx_device_limit_violation_login_attempt_id (login_attempt_id),
  INDEX idx_device_limit_violation_audit_event_id (audit_event_id),
  INDEX idx_device_limit_violation_device_limit_policy_id (device_limit_policy_id)
);
-- @@
CREATE TABLE IF NOT EXISTS device_session (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  identity_session_id UUID,
  app_user_id UUID NOT NULL,
  device_id UUID NOT NULL,
  licence_seat_id UUID NOT NULL,
  device_slot_id UUID NOT NULL,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_activity_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL,
  ended_at TIMESTAMPTZ,
  session_end_reason_id UUID,
  ip_address INET NOT NULL,
  authentication_method_id UUID NOT NULL,
  CONSTRAINT pk_device_session PRIMARY KEY (id),
  CONSTRAINT uq_device_session_identity_session_id UNIQUE (identity_session_id),
  CONSTRAINT ck_device_session_ended_range CHECK (ended_at IS NULL OR ended_at >= started_at),
  CONSTRAINT ck_device_session_end_reason_consistent CHECK ((ended_at IS NULL) = (session_end_reason_id IS NULL)),
  CONSTRAINT ck_device_session_expiry_range CHECK (expires_at >= started_at),
  CONSTRAINT ck_device_session_activity_range CHECK (last_activity_at >= started_at),
  CONSTRAINT fk_device_session_identity_session_id FOREIGN KEY (identity_session_id) REFERENCES identity_session (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_device_session_session_end_reason_id FOREIGN KEY (session_end_reason_id) REFERENCES session_end_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_device_session_authentication_method_id FOREIGN KEY (authentication_method_id) REFERENCES authentication_method (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_device_session_device_slot_id_licence_seat_id FOREIGN KEY (licence_seat_id, device_slot_id) REFERENCES device_slot (licence_seat_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_device_session_licence_seat_id_app_user_id FOREIGN KEY (licence_seat_id, app_user_id) REFERENCES licence_seat (id, app_user_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_device_session_device_id_app_user_id FOREIGN KEY (device_id, app_user_id) REFERENCES device (id, app_user_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_device_session_device_slot_id (device_slot_id) WHERE ended_at IS NULL,
  UNIQUE INDEX uq_device_session_device_id (device_id) WHERE ended_at IS NULL,
  INDEX idx_device_session_app_user_id_started_at (app_user_id, started_at DESC),
  INDEX idx_device_session_licence_seat_id (licence_seat_id) STORING (device_slot_id, expires_at, last_activity_at) WHERE ended_at IS NULL,
  INDEX idx_device_session_expires_at (expires_at) USING HASH WITH (bucket_count = 16) WHERE ended_at IS NULL,
  INDEX idx_device_session_started_at (started_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_device_session_session_end_reason_id (session_end_reason_id),
  INDEX idx_device_session_authentication_method_id (authentication_method_id)
) WITH (ttl_expiration_expression = '(ended_at + INTERVAL ''13 months'')', ttl_job_cron = '@daily');
-- @@
CREATE TABLE IF NOT EXISTS session_activity_sample (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  device_session_id UUID NOT NULL,
  sampled_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ip_address INET NOT NULL,
  endpoint_group STRING(40) NOT NULL,
  request_count INT4 NOT NULL,
  CONSTRAINT pk_session_activity_sample PRIMARY KEY (id),
  CONSTRAINT fk_session_activity_sample_device_session_id FOREIGN KEY (device_session_id) REFERENCES device_session (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  INDEX idx_session_activity_sample_sampled_at (sampled_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_session_activity_sample_device_session_id_sampled_at (device_session_id, sampled_at DESC)
) WITH (ttl_expiration_expression = '(sampled_at + INTERVAL ''30 days'')', ttl_job_cron = '@daily');
-- @@
CREATE TABLE IF NOT EXISTS session_revocation (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  device_session_id UUID,
  device_revocation_id UUID,
  app_user_id UUID NOT NULL,
  revoked_by_app_user_id UUID,
  revocation_source_id UUID NOT NULL,
  revocation_reason_id UUID NOT NULL,
  audit_event_id UUID,
  revoked_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT pk_session_revocation PRIMARY KEY (id),
  CONSTRAINT uq_session_revocation_device_session_id UNIQUE (device_session_id),
  CONSTRAINT fk_session_revocation_device_session_id FOREIGN KEY (device_session_id) REFERENCES device_session (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_session_revocation_device_revocation_id FOREIGN KEY (device_revocation_id) REFERENCES device_revocation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_session_revocation_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_session_revocation_revoked_by_app_user_id FOREIGN KEY (revoked_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_session_revocation_revocation_source_id FOREIGN KEY (revocation_source_id) REFERENCES revocation_source (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_session_revocation_revocation_reason_id FOREIGN KEY (revocation_reason_id) REFERENCES revocation_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_session_revocation_audit_event_id FOREIGN KEY (audit_event_id) REFERENCES audit_event (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  INDEX idx_session_revocation_device_revocation_id (device_revocation_id) WHERE device_revocation_id IS NOT NULL,
  INDEX idx_session_revocation_app_user_id_revoked_at (app_user_id, revoked_at DESC),
  INDEX idx_session_revocation_revoked_by_app_user_id (revoked_by_app_user_id) WHERE revoked_by_app_user_id IS NOT NULL,
  INDEX idx_session_revocation_audit_event_id (audit_event_id),
  INDEX idx_session_revocation_revocation_source_id (revocation_source_id),
  INDEX idx_session_revocation_revocation_reason_id (revocation_reason_id)
);
